1	//go:build linux
2	
3	package nettrace
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"net"
10		"net/netip"
11		"os"
12		"strconv"
13		"syscall"
14		"time"
15	
16		"golang.org/x/sys/unix"
17	)
18	
19	// defaultProbePort is the destination port of every probe, the traditional
20	// traceroute base port plus one: nothing normally listens there, so the target
21	// answers with Port Unreachable.
22	const defaultProbePort = 33435
23	
24	// probePayload is the neutral content of a probe.
25	var probePayload = []byte("abcdefghijklmnopqrstuvwabcdefghi")
26	
27	// errQueueBufLen sizes the control buffer for one IP_RECVERR message
28	// (cmsghdr, sock_extended_err and the offender's sockaddr).
29	const errQueueBufLen = 256
30	
31	var errNoExtendedErr = errors.New("no IP_RECVERR control message in the error queue")
32	
33	func supported() error { return nil }
34	
35	// systemProber returns the prober that uses the system's sockets.
36	func systemProber() prober { return linuxProber{} }
37	
38	// linuxProber probes with one connected, unprivileged UDP socket per TTL: the
39	// TTL is set with IP_TTL, IP_RECVERR makes the kernel queue the ICMP errors
40	// the probe provokes, and await reads them from the socket's error queue.
41	type linuxProber struct {
42		port int // destination port; 0 means defaultProbePort
43	}
44	
45	func (p linuxProber) open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error) {
46		port := p.port
47		if port == 0 {
48			port = defaultProbePort
49		}
50		d := net.Dialer{Control: func(_, _ string, c syscall.RawConn) error {
51			var serr error
52			if err := c.Control(func(fd uintptr) {
53				serr = unix.SetsockoptInt(int(fd), unix.IPPROTO_IP, unix.IP_TTL, ttl)
54				if serr == nil {
55					serr = unix.SetsockoptInt(int(fd), unix.IPPROTO_IP, unix.IP_RECVERR, 1)
56				}
57			}); err != nil {
58				return err
59			}
60			if serr != nil {
61				return os.NewSyscallError("setsockopt", serr)
62			}
63			return nil
64		}}
65		conn, err := d.DialContext(ctx, "udp4", net.JoinHostPort(dst.String(), strconv.Itoa(port)))
66		if err != nil {
67			var se *os.SyscallError
68			if errors.As(err, &se) && se.Syscall == "connect" {
69				return nil, connectError(err)
70			}
71			return nil, unsupportedSocketError(err)
72		}
73		udp := conn.(*net.UDPConn)
74		raw, err := udp.SyscallConn()
75		if err != nil {
76			_ = udp.Close()
77			return nil, err
78		}
79		return &linuxConn{conn: udp, raw: raw}, nil
80	}
81	
82	// unsupportedSocketError maps a socket or setsockopt failure that means "this
83	// system will not do unprivileged probing" to ErrUnsupported, keeping the raw
84	// error. Other errors (EMFILE...) are returned as they are.
85	func unsupportedSocketError(err error) error {
86		for _, errno := range []error{syscall.ENOPROTOOPT, syscall.EOPNOTSUPP, syscall.EPERM, syscall.EACCES} {
87			if errors.Is(err, errno) {
88				return fmt.Errorf("%w: %w", ErrUnsupported, err)
89			}
90		}
91		return err
92	}
93	
94	// connectError maps a connect failure. "Network unreachable" is ErrNoRoute; a
95	// refused connect is never ErrUnsupported.
96	func connectError(err error) error {
97		if errors.Is(err, syscall.ENETUNREACH) {
98			return fmt.Errorf("%w: %w", ErrNoRoute, err)
99		}
100		return err
101	}
102	
103	type linuxConn struct {
104		conn *net.UDPConn
105		raw  syscall.RawConn
106	}
107	
108	func (c *linuxConn) send() (time.Time, error) {
109		sentAt := time.Now()
110		if _, err := c.conn.Write(probePayload); err != nil {
111			return time.Time{}, err
112		}
113		return sentAt, nil
114	}
115	
116	// await reads the socket's error queue until an error arrives, until passes
117	// (errSilent) or ctx ends (ctx.Err()).
118	func (c *linuxConn) await(ctx context.Context, until time.Time) (reply, error) {
119		if err := ctx.Err(); err != nil {
120			return reply{}, err
121		}
122		if err := c.conn.SetReadDeadline(until); err != nil {
123			return reply{}, err
124		}
125		// Registered after the deadline is set, so the callback's past deadline
126		// always wins. ctx.Err() tells a cancellation from a timeout afterwards.
127		stop := context.AfterFunc(ctx, func() { _ = c.conn.SetReadDeadline(time.Unix(1, 0)) })
128		defer stop()
129	
130		oob := make([]byte, errQueueBufLen)
131		var oobn int
132		var recvErr error
133		err := c.raw.Read(func(fd uintptr) bool {
134			buf := make([]byte, 1)
135			for {
136				_, oobn, _, _, recvErr = unix.Recvmsg(int(fd), buf, oob, unix.MSG_ERRQUEUE|unix.MSG_DONTWAIT)
137				if recvErr != unix.EINTR {
138					break
139				}
140			}
141			return recvErr != unix.EAGAIN
142		})
143		switch {
144		case ctx.Err() != nil && err != nil:
145			return reply{}, ctx.Err()
146		case errors.Is(err, os.ErrDeadlineExceeded):
147			// When ctx's own deadline is not after until, the trace's deadline
148			// (not the probe timeout) is what ran out: let ctx report it.
149			if dl, ok := ctx.Deadline(); ok && !dl.After(until) {
150				<-ctx.Done()
151				return reply{}, ctx.Err()
152			}
153			return reply{}, errSilent
154		case err != nil:
155			return reply{}, err
156		case recvErr != nil:
157			return reply{}, os.NewSyscallError("recvmsg", recvErr)
158		}
159		return parseErrQueue(oob[:oobn])
160	}
161	
162	func (c *linuxConn) close() error { return c.conn.Close() }
163	
164	// parseErrQueue decodes the IP_RECVERR control message of a MSG_ERRQUEUE read.
165	func parseErrQueue(oob []byte) (reply, error) {
166		msgs, err := unix.ParseSocketControlMessage(oob)
167		if err != nil {
168			return reply{}, err
169		}
170		for _, m := range msgs {
171			if m.Header.Level == unix.SOL_IP && m.Header.Type == unix.IP_RECVERR {
172				return decodeExtendedErr(m.Data)
173			}
174		}
175		return reply{}, errNoExtendedErr
176	}
177

